128	// NodeGroupForNode returns the node group for the given node.
129	func (aws *awsCloudProvider) NodeGroupForNode(ctx context.Context, node *apiv1.Node) (cloudprovider.NodeGroup, error) {
130		if len(node.Spec.ProviderID) == 0 {
131			klog.Warningf("Node %v has no providerId", node.Name)
132			return nil, nil
133		}
134		ref, err := AwsRefFromProviderId(node.Spec.ProviderID)
135		if err != nil {
136			// Dropping this into V as it will be noisy with many Hybrid Nodes
137			klog.V(6).Infof("Node %v has unrecognized providerId: %v", node.Name, node.Spec.ProviderID)
138			return nil, nil
139		}
140		asg := aws.awsManager.GetAsgForInstance(*ref)
141	
142		if asg == nil {
143			return nil, nil
144		}
145	
146		return &AwsNodeGroup{
147			asg:        asg,
148			awsManager: aws.awsManager,
149		}, nil
150	}
