152	// HasInstance returns whether a given node has a corresponding instance in this cloud provider
153	func (aws *awsCloudProvider) HasInstance(ctx context.Context, node *apiv1.Node) (bool, error) {
154		// we haven't implemented a way to check if a fargate instance
155		// exists in the cloud provider
156		// returning 'true' because we are assuming the node exists in AWS
157		// this is the default behavior if the check is unimplemented
158		if strings.HasPrefix(node.GetName(), "fargate") {
159			return true, cloudprovider.ErrNotImplemented
160		}
161	
162		// avoid log spam for not autoscaled asgs:
163		//   Nodes that belong to an asg that is not autoscaled will not be found in the asgCache below,
164		//   so do not trigger warning spam by returning an error from being unable to find them.
165		//   Annotation is not automated, but users that see the warning can add the annotation to avoid it.
166		if node.Annotations != nil && node.Annotations["k8s.io/cluster-autoscaler-enabled"] == "false" {
167			return false, nil
168		}
169	
170		awsRef, err := AwsRefFromProviderId(node.Spec.ProviderID)
171		if err != nil {
172			return false, err
173		}
174	
175		// we don't care about the status
176		status, err := aws.awsManager.asgCache.InstanceStatus(*awsRef)
177		if status != nil {
178			return true, nil
179		}
180	
181		return false, fmt.Errorf("%s: %v", nodeNotPresentErr, err)
182	}
