225	// AwsRefFromProviderId creates AwsInstanceRef object from provider id which
226	// must be in format: aws:///zone/name
227	func AwsRefFromProviderId(id string) (*AwsInstanceRef, error) {
228		matches := validAwsRefIdRegex.FindStringSubmatch(id)
229		if matches == nil || len(matches) != 4 {
230			return nil, fmt.Errorf("wrong id: expected format aws:///<zone>/<name>, got %v", id)
231		}
232	
233		var parsedName string
234		if matches[1] != "" {
235			parsedName = matches[1]
236		} else {
237			parsedName = matches[2]
238		}
239	
240		return &AwsInstanceRef{
241			ProviderID: id,
242			Name:       parsedName,
243		}, nil
244	}
