292	func (ng *AwsNodeGroup) GetOptions(ctx context.Context, defaults config.NodeGroupAutoscalingOptions) (*config.NodeGroupAutoscalingOptions, error) {
293		if ng.asg == nil || ng.asg.Tags == nil || len(ng.asg.Tags) == 0 {
