299	// IncreaseSize increases Asg size
300	func (ng *AwsNodeGroup) IncreaseSize(ctx context.Context, delta int) error {
301		if delta <= 0 {
302			return fmt.Errorf("size increase must be positive")
303		}
304		size := ng.asg.curSize
305		if size+delta > ng.asg.maxSize {
306			return fmt.Errorf("size increase too large - desired:%d max:%d", size+delta, ng.asg.maxSize)
307		}
308		return ng.awsManager.SetAsgSize(ng.asg, size+delta)
309	}
